import {motionPlan} from './match3-motion.mjs';

export function createMatchEffects({root,asset,position,tokenAt,cellAt,animate,cue,reduced}){
  const layer=root.querySelector('#m3-board-fx');let epoch=0;const timers=new Map();
  function later(ms,fn=()=>{}){if(reduced.matches){fn();return Promise.resolve();}const generation=epoch;return new Promise(resolve=>{const id=setTimeout(()=>{timers.delete(id);try{if(generation===epoch)fn();}finally{resolve();}},Math.max(0,ms));timers.set(id,resolve);});}
  function node(cls,p,size){const e=document.createElement('span');e.className=cls;Object.assign(e.style,{left:`${p.x}px`,top:`${p.y}px`,width:`${size}px`,height:`${size}px`});layer.append(e);return e;}
  function transient(e,frames,options){return animate([e],frames,options).finally(()=>e.remove());}
  function ring(index,large=1){if(reduced.matches)return;const p=position(index),s=p.size*large,e=node('m3-impact-ring',{x:p.x-s/2,y:p.y-s/2},s);transient(e,[{transform:'scale(.2)',opacity:1},{transform:'scale(1.25)',opacity:0}],{duration:250});}
  function fragments(index,color,wood=false){if(reduced.matches)return;const p=position(index);for(let n=0;n<(wood?6:4);n++){const e=node('m3-spark'+(wood?' wood':''),p,wood?8:5),angle=index*1.2+n*2.1,radius=p.size*(.55+n*.08);e.style.background=wood?'#e8a64e':['#5ce28b','#f75e56','#ffd64f','#63bfff','#cf8aff'][color??2];transient(e,[{transform:'translate(-50%,-50%) scale(1)',opacity:1},{transform:`translate(${Math.cos(angle)*radius}px,${Math.sin(angle)*radius+25}px) rotate(200deg) scale(.15)`,opacity:0}],{duration:290+n*20,easing:'cubic-bezier(.1,.5,.3,1)'});}}
  function charge(index,power,delay){const token=tokenAt(index);if(!token||reduced.matches)return;later(delay,()=>{animate([token],[{filter:'brightness(1)',transform:'scale(1)'},{filter:'brightness(1.65)',transform:'scale(.83)'},{filter:'brightness(1.2)',transform:'scale(1.13)'}],{duration:85});ring(index,power==='orb'?1.8:1.2);});}
  function beam(index,power){const p=position(index),horizontal=power==='row',bounds=layer.getBoundingClientRect(),e=node('m3-beam '+power,p,6);e.style.width=horizontal?'100%':'6px';e.style.height=horizontal?'6px':'100%';if(horizontal)e.style.left='0';else e.style.top='0';transient(e,[{opacity:0,transform:horizontal?'scaleX(.02)':'scaleY(.02)'},{opacity:1,offset:.3},{opacity:0,transform:'scale(1)'}],{duration:240});for(const sign of[-1,1]){const rocket=node('m3-fx-rocket',{x:p.x-p.size/2,y:p.y-p.size/2},p.size);rocket.innerHTML=`<img src="${asset('premium-rocket')}" alt="">`;const angle=horizontal?sign*90:sign>0?180:0,dx=horizontal?sign*(bounds.width+40):0,dy=horizontal?0:sign*(bounds.height+40);transient(rocket,[{transform:`rotate(${angle}deg)`},{transform:`translate(${dx}px,${dy}px) rotate(${angle}deg)`}],{duration:250,easing:'cubic-bezier(.2,.15,.8,1)'});}}
  function blast(index,power,radius=2.5){const p=position(index),size=p.size*radius*2,e=node('m3-blast '+power,{x:p.x-size/2,y:p.y-size/2},size);transient(e,[{transform:'scale(.08)',opacity:1},{transform:'scale(.7)',opacity:.95,offset:.25},{transform:'scale(1.3)',opacity:0}],{duration:330});ring(index,radius*2);}
  function lightning(from,to){const a=position(from),b=position(to),e=document.createElementNS('http://www.w3.org/2000/svg','svg');e.setAttribute('width','100%');e.setAttribute('height','100%');e.classList.add('m3-lightning');e.innerHTML=`<path d="M${a.x} ${a.y} Q${(a.x+b.x)/2+20} ${(a.y+b.y)/2-25} ${b.x} ${b.y}"/>`;layer.append(e);transient(e,[{opacity:0},{opacity:1,offset:.2},{opacity:0}],{duration:180});}
  function collect(index,kind){const target=root.querySelector(`[data-goal="${kind}"] img`);if(!target||reduced.matches)return;const a=cellAt(index).getBoundingClientRect(),b=target.getBoundingClientRect(),r=root.getBoundingClientRect(),e=document.createElement('img');e.className='m3-goal-flight';e.src=asset(kind==='crate'?'premium-crate':'m3-mud');Object.assign(e.style,{left:`${a.left-r.left}px`,top:`${a.top-r.top}px`,width:`${a.width}px`});root.append(e);transient(e,[{transform:'scale(.6)',opacity:1},{transform:`translate(${(b.left-a.left)*.4+30}px,${(b.top-a.top)*.45-40}px) scale(.6)`,offset:.4},{transform:`translate(${b.left-a.left}px,${b.top-a.top}px) scale(.25)`,opacity:.2}],{duration:420,easing:'cubic-bezier(.35,.05,.7,.7)'});}
  function headline(text,combo=false){if(reduced.matches)return;const e=document.createElement('div');e.className='m3-celebration'+(combo?' combination':'');e.textContent=text;root.querySelector('.m3-board-space').append(e);transient(e,[{transform:'translate(-50%,-50%) scale(.6)',opacity:0},{transform:'translate(-50%,-50%) scale(1.09)',opacity:1,offset:.18},{transform:'translate(-50%,-55%) scale(1)',opacity:1,offset:.7},{transform:'translate(-50%,-70%) scale(.95)',opacity:0}],{duration:800,easing:'ease-out'});}
  async function clear(frame,{onHit=()=>{},onMud=()=>{},before}){
    if(reduced.matches)return;
    const plan=motionPlan(frame),consumed=new Set(frame.consumed||[]);cue(frame.activated.length?'power':'clear',frame.wave);
    if(frame.combo){headline(frame.combo.split(' · ')[0],true);const pair=[...consumed].map(i=>({i,p:position(i)}));if(pair.length===2){const mid={x:(pair[0].p.x+pair[1].p.x)/2,y:(pair[0].p.y+pair[1].p.y)/2};for(const a of pair){const t=tokenAt(a.i);animate([t],[{transform:'scale(1)',opacity:1},{transform:`translate(${mid.x-a.p.x}px,${mid.y-a.p.y}px) scale(.45)`,opacity:.1}],{duration:125,fill:'forwards'});}ring(pair[0]?.i??0,2.2);}}
    else if(frame.wave>=3)headline(frame.wave>=5?'精彩连消！':`${frame.wave} 连消`);
    const source=frame.activated.find(p=>p.power==='orb')?.index;
    for(const c of plan.conversions)later(c.at-70,()=>{if(source!==undefined)lightning(source,c.index);const t=tokenAt(c.index);if(t){t.className='m3-token '+c.power;t.querySelector('img').src=asset('premium-'+({row:'rocket',col:'rocket',bomb:'tnt',propeller:'propeller'}[c.power]));animate([t],[{transform:'scale(.45)',filter:'brightness(3)'},{transform:'scale(1.2)',filter:'brightness(1)'}],{duration:120});}});
    for(const p of plan.powers){if(!consumed.has(p.index))charge(p.index,p.power,Math.max(0,p.start-65));later(p.start,()=>{if(p.power==='row'||p.power==='col')beam(p.index,p.power);else if(p.power==='bomb'||p.power==='orb')blast(p.index,p.power,p.radius?p.radius+.5:2.5);if(p.power==='bomb'){animate([root.querySelector('.m3-board-area')],[{transform:'translate(0,0)'},{transform:'translate(-3px,2px)',offset:.2},{transform:'translate(2px,-1px)',offset:.5},{transform:'translate(0,0)'}],{duration:160});}});}
    for(const f of plan.flights)later(f.start,()=>{const a=position(f.from),b=position(f.to),e=node('m3-flying-propeller',{x:a.x-a.size/2,y:a.y-a.size/2},a.size);const t=tokenAt(f.from);if(t)t.style.opacity='0';e.innerHTML=`<img src="${asset('premium-propeller')}" alt="">${f.payload?`<img class="payload ${f.payload}" src="${asset('premium-'+(f.payload==='bomb'?'tnt':'rocket'))}" alt="">`:''}`;const dx=b.x-a.x,dy=b.y-a.y;transient(e,[{transform:'translate(0,0) scale(1)'},{transform:`translate(${dx*.25-24}px,${dy*.18-35}px) scale(1.6)`,offset:.33},{transform:`translate(${dx*.75-15}px,${dy*.65-20}px) scale(1.4)`,offset:.72},{transform:`translate(${dx}px,${dy}px) scale(.65)`}],{duration:f.duration,easing:'cubic-bezier(.3,.15,.65,1)'});later(f.duration,()=>ring(f.to,1.5));});
    for(const h of plan.hits)later(h.at,()=>{const t=tokenAt(h.index);if(!consumed.has(h.index))animate([t],[{transform:'scale(1)',opacity:1},{transform:'scale(1.13)',opacity:1,offset:.2},{transform:'scale(.25)',opacity:0}],{duration:95,fill:'forwards'});fragments(h.index,before.board[h.index]?.color);if(before.mud[h.index]){onMud(h.index);collect(h.index,'mud');}});
    for(const h of plan.crateHits)later(h.at,()=>{const t=cellAt(h.index)?.querySelector('.m3-crate');animate([t],[{transform:'rotate(-6deg) scale(1.08)'},{transform:'rotate(6deg)',offset:.4},{transform:`scale(${h.remaining?1:.4})`,opacity:h.remaining?1:0}],{duration:100,fill:'forwards'});fragments(h.index,null,true);onHit(h.index,h.remaining);if(!h.remaining)collect(h.index,'crate');});
    await later(plan.impactEnd);
  }
  function clearAll(){epoch++;for(const[id,resolve]of timers){clearTimeout(id);resolve();}timers.clear();layer.replaceChildren();root.querySelectorAll('.m3-celebration,.m3-goal-flight').forEach(e=>e.remove());}
  return{clear,clearAll,headline,ring};
}
